// Editorial source. IDs are stable anchors.
export const pages = [
  {
    slug: 'index', nav: 'The idea', title: 'A place to land. Room to move.',
    description: 'Community grounds, homes on wheels and shared civics infrastructure: an Australian proposal for greater choice and resilience.',
    hero: true,
    sections: [
      { id: 'the-purpose', title: 'The human purpose', html: `<div class="thesis"><span class="label">The human purpose</span><blockquote>From “How am I going to survive today?”<br>to “What am I going to do today?”</blockquote></div>` },
      { id: 'connected-ideas', title: 'Three connected ideas', html: `<section class="section"><div class="section-head"><h2>One strategy. Three connected parts.</h2><span>Start with a place. Build the support around it.</span></div><div class="pathways"><div class="pathway"><span class="index">01</span><h3>Community grounds</h3><p>Establish community grounds—utilising suitable regional showgrounds and public spaces—with amenities, energy, connectivity and spaces to work on things together.</p><a class="text-link" href="community-grounds.html">Explore the shared place ↗</a></div><div class="pathway"><span class="index">02</span><h3>The Walkabout Strategy</h3><p>Develop practical support to obtain, finance and maintain a second-hand home on wheels, with a suitable tow vehicle where needed.</p><a class="text-link" href="walkabout.html">Explore the personal pathway ↗</a></div><div class="pathway"><span class="index">03</span><h3>Civics & digital infrastructure</h3><p>Connect local energy, edge databoxes and open tools to empower community-led civics activities.</p><a class="text-link" href="infrastructure.html">Explore the wider network ↗</a></div></div></section>` },
      { id: 'solarpunk-vision', title: 'Embracing the Solarpunk vision', html: `<section class="section"><div class="section-head"><h2>Embracing the Solarpunk vision</h2><span>Radical optimism · Energy democracy · Community resilience</span></div><p>The Solarpunk movement is a radically optimistic philosophy that envisions a sustainable, egalitarian future. It rejects climate doomerism, advocating instead for a world where humanity, nature, and technology co-exist in peaceful harmony. All enduring societies depend upon social foundations provided on a non-exploitative, usury-free basis.</p><div class="note"><p><em>“Solarpunk acts as a future imaginary to subvert climate fatalism, prioritising energy democracy, mutual resilience, and non-exploitative social foundations with community-oriented optimism.”</em></p></div><p>By championing decentralisation, renewable energy, and cooperative community strength, the Solarpunk ethos underpins everything we are building—redefining transitional infrastructure and securing fundamental rights to privacy, personal autonomy, and informational self-determination for all participants.</p><div class="table-wrap"><table><thead><tr><th>Community Objective</th><th>Solarpunk Principle</th><th>Tangible Deployment</th></tr></thead><tbody><tr><td><strong>Asset Creation & Autonomy</strong></td><td>Non-exploitative social foundations</td><td>All societies depend upon social foundations provided on a peaceful, non-exploitative (usury-free) basis. Tailored pathways and maintenance hubs for second-hand ‘homes on wheels’ build real personal assets and autonomy rather than compounding crisis debt or perpetual subsidies.</td></tr><tr><td><strong>Clean Energy & Resilience</strong></td><td>Eco-Technological Harmony</td><td>Commercial-scale solar, battery storage, and islandable microgrids at regional community grounds.</td></tr><tr><td><strong>Informational Self-Determination & Local AI</strong></td><td>Individual autonomy & decentralisation</td><td>W3C Solid-compatible portable data pods, offline-first edge controllers (<a href="https://github.com/mediaprophet/Solid-CSS-Databox">Solid-CSS-Databox ↗</a>), and community AI hubs—leveraging open standards that enable interoperability across systems created with various technologies.</td></tr></tbody></table></div></section>` },
      { id: 'how-it-connects', title: 'How it connects', html: `<section class="section"><div class="section-head"><h2>A secure base can open up choices.</h2><span>The intended pathway—not a proven outcome</span></div><div class="flow"><div><span class="index">01 / Arrive</span><strong>A viable place to stay</strong><p>A suitable mobile home and a ground with the everyday essentials.</p></div><div><span class="index">02 / Stabilise</span><strong>Costs you can plan around</strong><p>Understand the full weekly budget, repairs and available support.</p></div><div><span class="index">03 / Reconnect</span><strong>Space to take part</strong><p>Study, work, care for family, share a skill or take time to recover.</p></div><div><span class="index">04 / Choose</span><strong>A next step of your own</strong><p>Stay where permitted, travel, relocate for work or move into another home. <a href="journey-out.html">The journey out ↗</a></p></div></div></section>` },
      { id: 'who-it-could-help', title: 'Who it could help', html: `<section class="section"><h2>Life changes. People need options.</h2><div class="two-col"><div><p>The initiative supports people navigating major life transitions: recovering from financial setbacks or relationship breakdown, caring for family, returning from defence service, studying, or establishing independent livelihoods.</p></div><div><p>It also includes travellers, remote workers and people who can cover their own costs but want an autonomous, sustainable way to live. Participation is not defined by poverty or by a single bureaucratic label.</p></div></div><div class="note"><p>A mobile home will not suit everyone. This proposal expands people's choices alongside permanent housing and specialist support, with suitability and access worked out through regional demonstration sites.</p></div><a class="text-link" href="review.html">Read the assumptions and open questions ↗</a></section>` }
    ]
  },
  {
    slug: 'community-grounds', nav: 'Community grounds', title: 'A shared place to stay, contribute and begin again.',
    description: 'How community grounds—utilising suitable regional showgrounds and shared public sites—provide everyday amenities, renewable energy and spaces for purposeful activity.',
    eyebrow: '01 / Community grounds', intro: 'Start with a place the community already uses. Add the infrastructure that makes it useful in more ways, for more of the year.',
    sections: [
      { id: 'the-proposition', title: 'The proposition', html: `<p>Rather than treating alternative housing as a systemic failure, we are establishing an innovative, dignified framework for modern nomadic living and transition. Developed regions increasingly rely on a mobile workforce to fill critical seasonal and skilled employment gaps; however, current urban modernisation efforts often marginalise or criminalise alternative living. By shifting public focus away from perpetual crisis management toward catalytic asset creation, we aim to reduce public expense and drastically improve quality of life, empowering capable individuals to transition from survival mode to productive, autonomous living.</p><h3>Supporting milestones, not just mobility</h3><p>Beyond simply providing a place to park, true autonomy requires space, dignity, and stability for fundamental human life stages:</p><ul><li><strong>A structural stepping stone for study:</strong> provides an accessible launchpad for young adults who wish to pursue vocational training, university degrees, or technical apprenticeships but are priced out by crushing urban rental markets.</li><li><strong>Dignified foundation for raising children:</strong> creates an affordable, secure environment for young people and families choosing to have and raise children, offering community stability without the burden of unserviceable 30-year housing debt.</li><li><strong>Cognitive agency & financial bandwidth:</strong> capping foundational living costs restores the mental clarity and financial headroom necessary for individuals and families to plan their long-term futures rather than expending all their energy on day-to-day survival.</li></ul><h3>Protecting the grassroots innovator</h3><p>A critical flaw in modern economic development is the stark disparity between capital and creation: physical infrastructure and government grants are frequently funded, while the grassroots innovators utilising them often live below the poverty line, taking on crushing personal debts while attempting to build an economic future for themselves and their communities.</p><ul><li><strong>Transition from survival to focused enterprise:</strong> by eliminating predatory overheads, creators can focus sustained time, creative energy, and trade craft on building tangible civics solutions and small ventures.</li><li><strong>Rejecting the extractive "start-up hub" model:</strong> our framework deliberately rejects conventional incubator dynamics, which too often expose unprotected creators to opportunistic vendors, corporate middlemen, and venture scouts seeking to harvest ideas from founders who cannot afford costly litigation to defend their intellectual property.</li><li><strong>Protection of creators' moral &amp; material interests:</strong> rooted in the fundamental human right to the protection of moral and material interests in one's creations (UDHR Art. 27), decentralised, W3C Solid-interoperable data pods and verifiable git/SVN-like resource commits ensure creators retain direct ownership and provenance over their work across diverse technologies, ensuring grassroots innovation directly advances the creator's own economic security rather than being captured by well-funded intermediaries.</li></ul><h3>Generative infrastructure, not an extractive toll-booth</h3><p>Traditional housing and commercial caravan parks operate on an extractive landlord model, treating residents as the primary financial engine expected to bear capital debt and overheads through high fees. Community grounds fundamentally invert this dynamic. The site sustains itself through <strong>generative physical and digital infrastructure</strong>—commercial-scale rooftop solar, battery grid arbitrage, and edge compute databoxes. Because the infrastructure produces independent revenue streams, the ground does not need to extract high rents from people in transition. Operating overheads are decoupled from resident fees, allowing the site to offer a guaranteed, non-extractive <strong>$15 per night ($105/week) concession floor</strong> for essential shelter.</p><h3>Bridging the infrastructure gap</h3><p>While many regional show-grounds already feature foundational infrastructure—such as large sheds, public toilets, sports facilities, and existing electrical connections—they frequently lack the dedicated amenities and energy capacity required to support transitional living. Currently, there is no normative framework to employ and advance the use of this infrastructure to facilitate this purpose. To bridge this gap, our strategic plan:</p><ul><li><strong>Conducts tailored site assessments:</strong> evaluating structural capacity, electrical loads, and planning considerations for every candidate ground.</li><li><strong>Upgrades core utilities:</strong> deploying commercial-scale solar, battery storage, and upgraded ablution blocks to transform day-use facilities into functional living spaces.</li><li><strong>Builds disaster resilience:</strong> establishing islandable microgrids that provide emergency power, water access, and communications during disruptions.</li><li><strong>Fosters local enterprise & fills workforce gaps:</strong> providing spaces where individuals can study, retrain, work remotely, or maintain vehicles without crushing overhead costs.</li></ul><div class="note"><p><strong>Keep the ground a community asset.</strong> Shows, sport, festivals and local organisations remain part of its core purpose. Transitional accommodation works alongside these traditions, supported by clear scheduling protocols during major event periods.</p></div><h3>A local blueprint for global development</h3><p>By perfecting this model domestically, we are creating a deployable framework that directly supports international Sustainable Development Goals (SDGs). Establishing decentralised utility networks and digital transformation in regional Australia serves as a practical blueprint for bringing vital infrastructure to developing regions worldwide facing acute energy, clean water, and connectivity deficits.</p><ul><li><strong>High-bandwidth digital hubs:</strong> aligning with international efforts like UNICEF's Project Connect by treating community grounds as digital access and education hubs.</li><li><strong>The right to privacy &amp; informational self-determination:</strong> leveraging open, W3C Solid-compatible standards to uphold the fundamental human right to privacy and informational self-determination, ensuring residents maintain personal autonomy over portable data pods across heterogeneous systems while seamlessly accessing local microgrids and services.</li><li><strong>Targeted SDG delivery:</strong> creating verifiable outcomes for affordable clean energy (SDG 7), industry, innovation & infrastructure (SDG 9), and resilient communities (SDG 11).</li></ul>` },
      { id: 'everyday-essentials', title: 'What a ground could provide', html: `<div class="numbered"><span class="index">01</span><div><h3>Everyday essentials & ablutions</h3><p>Upgraded ablution blocks, drinking water, modern laundry, reliable wastewater management and high-speed connectivity, designed for dignity, accessibility and personal privacy.</p></div></div><div class="numbered"><span class="index">02</span><div><h3>Community-scale renewable energy</h3><p>Commercial-scale rooftop solar, community battery storage, and smart IoT metering that enables dynamic peer-to-peer energy matching between local generation and site demand—reducing diesel generator reliance and powering both events and medium-term stays.</p></div></div><div class="numbered"><span class="index">03</span><div><h3>Community maintenance & project hubs</h3><p>Multi-purpose facilities and shared workshops where residents and locals can study, work remotely, share skills, and maintain vehicles to keep setups roadworthy and safe.</p></div></div><div class="numbered"><span class="index">04</span><div><h3>Designated mobile home bays</h3><p>Engineered vehicle access, utility hookups, generous spacing, and clear stay agreements that ensure dwellings and the site operate together harmoniously.</p></div></div>` },
      { id: 'shared-use', title: 'One ground, several uses', html: `<div class="table-wrap"><table><thead><tr><th>Setting</th><th>What the ground supports</th><th>Practical considerations</th></tr></thead><tbody><tr><td><strong>Everyday life</strong></td><td>Transitional living, local club activities, study, remote work and vehicle maintenance.</td><td>Access protocols, modest site contributions, shared amenities care and quiet zones.</td></tr><tr><td><strong>Shows & major events</strong></td><td>Traditional agricultural shows, sports fixtures and festivals powered by upgraded renewable capacity and modern facilities.</td><td>Peak booking coordination, surge power management and planned mobility arrangements during major show weeks.</td></tr><tr><td><strong>Disruption & resilience</strong></td><td>Community coordination hub with battery-backed power, water access and communications during emergency disruptions.</td><td>Safety protocols, essential circuit prioritisation and coordination with local emergency services.</td></tr></tbody></table></div><p class="small">Renewable microgrid assets provide vital local resilience and reduce operational bills, while grid interconnects ensure long-term stability.</p>` },
      { id: 'local-stewardship', title: 'Make the local arrangements work', html: `<p>Delivering community grounds shifts economic focus from recurring crisis management to catalytic asset creation, combining public and philanthropic co-investment with self-sustaining local operations.</p><ul><li><strong>Land and buildings:</strong> partner with local councils, agricultural societies and community ground trusts who steward the land and facilities.</li><li><strong>Tiered pricing & cross-subsidisation:</strong> implement a tiered fee schedule where full-fee visitors and commercial events cross-subsidise the $15/night concession floor, reinforced by local solar energy sales.</li><li><strong>Agreements & co-investment:</strong> establish clear roof-space leases, shared solar asset governance, and equitable distribution of generated energy and cost savings.</li><li><strong>Local operations:</strong> deploy transparent management for site stays, maintenance, utility contributions and community spaces.</li><li><strong>Community participation:</strong> ensure residents and local organisations have a voice in site stewardship, voluntary initiatives and shared rules.</li><li><strong>Site feasibility:</strong> complete tailored engineering, zoning, bushfire/flood risk, and grid connection assessments for every candidate site before launch.</li></ul>` },
      { id: 'first-ground', title: 'What to learn from a first ground', html: `<p>A flagship demonstration ground will validate how foundational upgrades, mobile living and shared energy work in practice. The initiative focuses on capable individuals facing life transitions—such as financial hardship, relationship separation or seeking an intentional nomadic lifestyle—who have modest income, desire autonomy, and benefit from an empowering strategic reset rather than institutional dependency.</p><div class="two-col"><div><h3>For residents</h3><p>Does the site provide predictable, low-cost living for concession card holders (at the $15/night electronic tariff within a ~$600/week baseline)? Is the $15 floor fully protective even during severe illness? Are amenities and microgrids dependable? Does autonomy and stability allow people to plan their next chapter with dignity?</p></div><div><h3>For the host town</h3><p>Do local businesses, clubs and annual shows gain from enhanced facilities and reliable clean energy? Does the asset-building model deliver lasting local value?</p></div></div>` }
    ], next: 'walkabout'
  },
  {
    slug: 'walkabout', nav: 'Walkabout Strategy', title: 'A home on wheels needs a whole support system.',
    description: 'The Walkabout Strategy connects suitable mobile homes and tow vehicles with affordability, repairs and places to stay.',
    eyebrow: '02 / The Walkabout Strategy', intro: 'The vehicle is one part of the pathway. The full proposition connects a suitable home, manageable costs, trusted repair support and somewhere to stay.',
    sections: [
      { id: 'choice-and-suitability', title: 'Start with the person or family', html: `<p>The Walkabout Strategy establishes an empowering, community-supported pathway into affordable campers, caravans, campervans, and tow vehicles. It connects directly to community grounds while providing the practical ecosystem required to sustainably own, maintain, and live in a mobile home.</p><p>The intention is to support fundamental human life milestones on people's own terms: enabling young adults to pursue study without crushing urban rental debt; providing young people and families a dignified, affordable foundation to raise children with community stability; giving grassroots innovators the living security to build ventures without living below the poverty line; and offering an autonomous reset after relationship changes, caring duties, or financial setbacks.</p><div class="note"><p><strong>Suitability comes first.</strong> Explore household space, accessibility, driving capacity, schooling, healthcare, pets and proximity to personal support. A lower purchase price does not by itself make a setup suitable.</p></div>` },
      { id: 'the-support-pathway', title: 'The support pathway', html: `<div class="numbered"><span class="index">01</span><div><h3>Understand the options</h3><p>Work out what the person needs from the dwelling and location, what they can afford, and whether mobile living is a useful option for them.</p></div></div><div class="numbered"><span class="index">02</span><div><h3>Find a suitable setup</h3><p>Prioritising reliable, affordable second-hand homes on wheels (caravans, campervans, or converted vehicles), supported by an independent pre-purchase inspection framework to verify roadworthiness, structural condition, and tow vehicle compatibility.</p></div></div><div class="numbered"><span class="index">03</span><div><h3>Work out the complete cost</h3><p>Consider purchase or finance costs alongside site fees, fuel, insurance, registration, essential living expenses and a repair reserve. Financing is an idea to develop; no product or lender is established here.</p></div></div><div class="numbered"><span class="index">04</span><div><h3>Keep it usable</h3><p>Connect people with mechanics, repair services, tools and opportunities to learn. Shared workshops can support practical skills, with qualified help for work that needs it.</p></div></div><div class="numbered"><span class="index">05</span><div><h3>Support the next step</h3><p>Plan for changes in income, breakdowns, moving between grounds and eventually selling or leaving the setup. A workable exit matters as much as entry. <a href="journey-out.html">Explore the journey out ↗</a></p></div></div>` },
      { id: 'weekly-picture', title: 'Look at the whole weekly picture', html: `<p>Traditional housing models default to an extractive paradigm, assuming vulnerable residents must bear the full capital and debt burden of the physical site. In contrast, community grounds sustain their baseline operations through <strong>generative physical and digital infrastructure</strong>: commercial-scale rooftop solar exports, battery grid trading, and edge compute databoxes. Because these assets generate external revenue, the ground does not need to extract high rents from residents.</p><h3>Clarifying the "30% Rule": Percentage of fee vs. percentage of income</h3><p>In Australian affordable housing policy, the standard benchmark defines shelter as affordable if it costs no more than <strong>30% of gross income</strong>. For an Australian concession card holder (Age Pension, Disability Support Pension, Carer Payment, JobSeeker with energy supplements) on roughly <strong>A$600 per week</strong>, the conventional housing stress ceiling would be <strong>$180 per week</strong>.</p><p>Under the Community Grounds model, however, <strong>the concession rate is set at 30% of the full commercial fee</strong>. With full commercial rates benchmarked at $50 per night ($350/week, matching standard regional holiday parks), the <strong>concession floor is $15 per night ($105 per week)</strong>—a 70% discount. In relation to income, $105/week represents <strong>only 17.5% of a $600/week concession income</strong>, sitting far below the housing stress ceiling and providing an essential $75/week safety cushion.</p><h3>A universal safety net: Protection during illness</h3><p>The $15/night ($105/week) tariff is a <strong>universal, non-conditional safety net</strong>. It is never conditional on mandatory labour or sweat equity. Even if a resident is severely unwell, bedridden, disabled, or temporarily unable to contribute to cooperative projects, their site stay is completely secure. The remaining <strong>$495 per week</strong> preserves food security, essential PBS-subsidised medication, phone connectivity, and vehicle roadworthiness—permanently breaking the recurring cycle of crisis debt.</p><h3>Tiered pricing architecture</h3><p>Because commercial solar export and edge compute absorb the bulk of the grounds' baseline operational costs, fee structures simply manage marginal capacity across distinct community cohorts:</p><div class="table-wrap"><table><thead><tr><th>Pricing Tier</th><th>Nightly Tariff</th><th>Weekly Total</th><th>Cohort Profile</th><th>Role in Community Grounds Ecosystem</th></tr></thead><tbody><tr><td><strong>Tier 1: Concession Floor</strong></td><td><strong>$15 / night</strong> <span class="small">(30% of full fee)</span></td><td><strong>$105 / wk</strong></td><td>Concession card holders, pensioners, people recovering from illness or crisis.</td><td><strong>Universal safe haven:</strong> Pure non-extractive baseline covering direct marginal consumables (potable water, wastewater treatment, amenities).</td></tr><tr><td><strong>Tier 2: Nomad / General</strong></td><td><strong>$30 – $35 / night</strong> <span class="small">(~65% of full fee)</span></td><td><strong>$210 – $245 / wk</strong></td><td>Mobile trade workers, seasonal workers, funded students, road-trippers.</td><td>Covers full marginal resource use and contributes directly to the ground's ongoing maintenance and tooling reserve.</td></tr><tr><td><strong>Tier 3: Commercial / Full</strong></td><td><strong>$50 / night</strong> <span class="small">(100% of full fee)</span></td><td><strong>$350 / wk</strong></td><td>Salaried remote workers, holiday tourists, event and show visitors.</td><td>Aligns with regional holiday park benchmarks; provides secondary cross-subsidisation alongside primary solar and compute exports.</td></tr></tbody></table></div><div class="budget" data-budget><h3>Weekly scenario: Concession card holder baseline</h3><p class="small">All amounts are Australian dollars per week. Convert annual bills to weekly amounts before entering them. Figures update dynamically and are not stored.</p><div class="budget-grid"><label for="income">Available income (Concession baseline) <span class="money-input">$<input id="income" type="number" min="0" max="1000000" step="1" value="600"></span></label><label for="site">Site fees & utilities ($15/night electronic payment) <span class="money-input">$<input id="site" type="number" min="0" max="1000000" step="1" value="105"></span></label><label for="finance">Home / vehicle loan repayments <span class="money-input">$<input id="finance" type="number" min="0" max="1000000" step="1" value="90"></span></label><label for="food">Food + household essentials <span class="money-input">$<input id="food" type="number" min="0" max="1000000" step="1" value="120"></span></label><label for="travel">Fuel + local transport <span class="money-input">$<input id="travel" type="number" min="0" max="1000000" step="1" value="50"></span></label><label for="insurance">Insurance + concessional registration <span class="money-input">$<input id="insurance" type="number" min="0" max="1000000" step="1" value="40"></span></label><label for="repairs">Vehicle & maintenance reserve <span class="money-input">$<input id="repairs" type="number" min="0" max="1000000" step="1" value="45"></span></label><label for="other">Health (PBS), phone + personal <span class="money-input">$<input id="other" type="number" min="0" max="1000000" step="1" value="50"></span></label></div><div class="budget-result" data-result role="status" aria-live="polite" aria-atomic="true"></div><noscript><p>This interactive illustration needs JavaScript. The starting concession example totals $500 in weekly costs ($105 site fees at $15/night plus $395 in living, vehicle and repair reserves), leaving $100 from a $600 weekly concession income.</p></noscript></div><p class="small">Baseline figures reflect Australian concession allowances, statutory registration concessions, and the standard $15/night community ground electronic tariff. Actual figures will vary according to vehicle loan structure, regional travel distance, and personal living needs.</p>` },
      { id: 'questions-to-resolve', title: 'What the pathway still needs', html: `<ul><li>A way to assess dwelling condition, vehicle suitability and likely maintenance costs before purchase.</li><li>A financing model with clear total costs, ownership terms and arrangements when circumstances change.</li><li>Reliable places to stay, including during shows or other periods when a ground is unavailable.</li><li>Practical support when a home or vehicle needs major repairs.</li><li>Evidence about who benefits, who is excluded by cost or design, and which other housing options people need.</li></ul><p>The intended result is more agency and stability. The pilot needs to test that result from residents' perspectives, including people who choose to leave.</p>` }
    ], next: 'infrastructure'
  },
  {
    slug: 'infrastructure', nav: 'Civics infrastructure', title: 'Start at the ground. Design for the wider community.',
    description: 'An Australian starting point for shared energy, digital services and civics infrastructure that other communities could adapt.',
    eyebrow: '03 / Civics infrastructure', intro: 'Community grounds provide the physical and digital foundations for civics activities—empowering individuals and communities to collaborate on shared energy, open tools, and local resilience.',
    sections: [
      { id: 'energy', title: 'Make energy useful locally', html: `<div class="note"><p><strong>Civics, not civic:</strong> “Civic” often denotes government agencies or municipal bureaucracy. But government cannot and will not employ everyone using these grounds or be the sole beneficiary of their work. Instead, residents and locals are directly engaging in <strong>civics activities</strong>—community-led problem solving, mutual aid, hands-on enterprise, and shared stewardship—which in turn benefit the entire town. Civics infrastructure provides the practical energy, physical amenities, and open tools required to make this work possible.</p></div><p>Local energy metering and telemetry form an essential early building block. Understanding precise generation and consumption profiles helps operators manage tariffs, plan storage upgrades, and match daytime solar with productive community activities.</p><div class="flow"><div><span class="index">01</span><strong>Generate</strong><p>Assess solar on suitable roofs or other available space.</p></div><div><span class="index">02</span><strong>Measure</strong><p>Understand when energy is produced and where it is needed.</p></div><div><span class="index">03</span><strong>Coordinate</strong><p>Explore storage and activities whose timing can be adjusted.</p></div><div><span class="index">04</span><strong>Extend</strong><p>Investigate participation by local clubs, households and farms.</p></div></div><p>For example, daytime generation and evening sports lighting happen at different times. A proposal to lower lighting costs needs to account for that timing, storage and the actual supply arrangements.</p><div class="note"><p><strong>A development direction, not an operating energy market.</strong> Metering, billing, energy sharing and power supply are different functions. Their technical and commercial arrangements need to be established before promising lower prices or energy trading.</p></div>` },
      { id: 'flexible-uses', title: 'Explore useful flexible demand', html: `<p>Some uses of electricity may be able to run at times when more local generation is available. The discussion explores connecting this flexibility to practical community services.</p><div class="two-col"><div><h3>Questions for a pilot</h3><p>Which activities can change their timing? What equipment and controls are needed? Do operating savings justify those costs? Does the service still work when generation is low?</p></div><div><h3>An idea needing separate study</h3><p>The author mentions plastic pyrolysis—processing plastics using heat with limited oxygen—as a possible use of surplus energy. This is an exploratory example, not a selected technology or a demonstrated environmental benefit.</p></div></div><p class="small">Any proposed waste-processing activity needs its own technical, environmental, operational and economic assessment. The community grounds concept does not depend on adopting it.</p>` },
      { id: 'digital', title: 'Digital services with human control', html: `<p>Decentralised digital architecture is vital to ensure community infrastructure operates under user control rather than corporate surveillance. Utilising open-standard, W3C Solid-interoperable data pods and edge appliances allows residents to store personal credentials and energy telemetry securely on-site. The key benefit of Solid is that it provides an open standard that enables seamless interoperability between independent systems that may be built using various technologies.</p><p>Solid describes an open specification in which people keep data in portable stores called Pods and control application access across multiple independent tools and platforms. <a href="https://solidproject.org/about">Read the Solid project's explanation ↗</a></p><p>This foundation powers our dedicated edge infrastructure—including local transactive microgrids, containerised databoxes, and offline-first AI orchestration hubs.</p><div class="note"><p><strong>Explore the full digital architecture:</strong> Read our detailed breakdown of edge databoxes, transactive energy trading, and local AI hubs on the <a href="digital-economy.html">Digital economy page ↗</a>.</p></div>` },
      { id: 'international', title: 'An Australian starting point, a wider horizon', html: `<p>Domestic solutions at regional community grounds are designed strategically to be adapted in developing regions, supporting international goals such as affordable clean energy, high-bandwidth connectivity, and disaster-resilient community hubs.</p><p><a href="https://projectconnect.unicef.org/">UNICEF's Project Connect ↗</a> provides a vital international benchmark for mapping connectivity and establishing school and community grounds as digital transformation access nodes.</p><p>The opportunity is to share what is learned about infrastructure, operations and human needs. A model developed at an Australian community ground would still need to be redesigned with each community's institutions, climate, resources and priorities.</p><h3>What would make the learning reusable?</h3><ul><li>Documented components and the conditions under which they work.</li><li>Transparent costs, maintenance needs and evidence of outcomes.</li><li>Digital interfaces and data practices that can be understood and adapted.</li><li>Local governance and meaningful participation in decisions.</li></ul>` }
    ], next: 'digital-economy'
  },
  {
    slug: 'digital-economy', nav: 'Digital economy', title: 'Standards-based community services, edge databoxes and local AI.',
    description: 'Activating the local digital economy with W3C Solid-interoperable data pods, offline-first edge controllers (Solid-CSS-Databox), transactive microgrids, and community AI orchestration hubs.',
    eyebrow: '04 / Digital economy', intro: 'Transforming regional community grounds into high-bandwidth civics innovation hubs through open-source edge databoxes, informational self-determination, and privacy-preserving local AI.',
    sections: [
      { id: 'local-digital-economy', title: 'Empowering the local digital economy', html: `<p>Community grounds serve as catalytic launchpads for local digital economies, marrying physical energy networks with decentralised digital services.</p><div class="numbered"><span class="index">01</span><div><h3>Decentralised energy markets</h3><p>Smart IoT metering enables dynamic peer-to-peer energy matching between rooftop solar generators, battery reserves and community consumers, establishing local resilience and fair pricing.</p></div></div><div class="numbered"><span class="index">02</span><div><h3>Autonomous transactive trading</h3><p>An intelligent local grid allows residents to negotiate power rates or trade surplus battery storage the moment they plug in, turning mobile dwellings into active microgrid participants.</p></div></div><div class="numbered"><span class="index">03</span><div><h3>Civics innovation hubs</h3><p>Treating community grounds as high-bandwidth digital access hubs fosters local enterprise, provides remote study environments, and empowers digital nomads to rebuild professional practices without crushing urban overheads.</p></div></div>` },
      { id: 'standards-based-services', title: 'Standards-based digital services', html: `<p>To ensure human autonomy and prevent corporate lock-in, all digital community interactions build upon open standards and user-owned data architecture. The core strength of W3C Solid is that it provides an open standard that enables seamless interoperability between systems created using various technologies—preventing vendor lock-in and allowing modular tools to communicate freely.</p><ul><li><strong>Informational self-determination:</strong> grounded in the fundamental right to privacy (UDHR Art. 12, ICCPR Art. 17), residents maintain personal data pods under open, W3C Solid-compatible architecture where they retain individual autonomy over their identity, personal records and service permissions.</li><li><strong>Frictionless mobility:</strong> users take their verified micro-finance history, maintenance logs and community credentials with them as they move between grounds, avoiding institutional gatekeeping and administrative friction across diverse software stacks.</li><li><strong>Unified physical-digital access:</strong> a cryptographic, W3C Solid-interoperable profile serves as a seamless universal key for accessing site microgrids, upgraded ablution blocks, shared tool workshops and high-speed internet.</li></ul><div class="note"><p><strong>Interoperability by design:</strong> By relying on open specifications rather than proprietary vendor APIs, W3C Solid-compatible data pods guarantee that digital participation remains voluntary, portable, and vendor-neutral—enabling diverse systems created using various technologies to interoperate while keeping data under individual control.</p></div>` },
      { id: 'edge-building-blocks', title: 'Edge architecture & Solid-CSS-Databox', html: `<p>The digital foundation is designed to function reliably in regional, remote and developing environments where central cloud connections may be fragile or costly.</p><p>Drawing on the architecture demonstrated in the open-source <a href="https://github.com/mediaprophet/Solid-CSS-Databox">Solid-CSS-Databox ↗</a> repository, our technical stack operates directly at the community edge:</p><div class="two-col"><div><h3>Modular containerised stack</h3><p>An offline-first, containerised Community Solid Server (CSS) and IoT telemetry pipeline running locally on Linux edge controllers—implementing W3C Solid-interoperable open specifications to manage energy telemetry, micro-billing, access permissions and local networking across diverse hardware.</p></div><div><h3>Zero SaaS licensing overhead</h3><p>Built entirely with open-source edge software, eliminating recurring vendor fees and centralised cloud subscriptions so regional community grounds and developing communities can deploy without debt.</p></div></div><div class="note"><p><strong>Uplifting human value &amp; equity:</strong> Beyond monetary accounting, the local digital layer provides voluntary tools to uplift human equity—recognising and validating informal skills, mutual aid, peer mentoring and community stewardship that traditional markets ignore.</p></div>` },
      { id: 'community-ai-hubs', title: 'Community AI orchestration hubs', html: `<p>To maximise the utility of local digital infrastructure, each community ground hosts an open-source AI orchestration hub designed specifically for civics empowerment, microgrid balancing and resident autonomy.</p><div class="flow"><div><span class="index">01</span><strong>Offline intelligence</strong><p>Local open-source models run on Linux edge hardware, fully operational during grid or telecom outages.</p></div><div><span class="index">02</span><strong>Microgrid dispatch</strong><p>Automates P2P energy matching and routes surplus solar to water purification or plastic pyrolysis.</p></div><div><span class="index">03</span><strong>Private resident support</strong><p>Queries private Solid pods with local inference, keeping habits and personal data completely confidential.</p></div><div><span class="index">04</span><strong>Skill & task matching</strong><p>Connects resident capabilities with ground maintenance, local council tasks and community enterprise.</p></div></div><p>By executing inference directly at the edge against decentralised, W3C Solid-compatible pods, the community AI hub acts as a civics intelligence hub without transmitting sensitive citizen information to commercial cloud providers.</p>` },
      { id: 'global-sdg-alignment', title: 'Global impact & SDG alignment', html: `<p>By proving this decentralised utility and digital framework domestically in regional Australia, we create a deployable blueprint for communities worldwide facing acute energy and infrastructure deficits.</p><div class="table-wrap"><table><thead><tr><th>Objective</th><th>Implementation mechanism</th><th>Targeted UN SDG</th></tr></thead><tbody><tr><td><strong>Affordable clean energy</strong></td><td>Commercial rooftop solar, battery storage, IoT metering and P2P transactive microgrids.</td><td><strong>SDG 7:</strong> Affordable & Clean Energy</td></tr><tr><td><strong>Resilient community infrastructure</strong></td><td>Offline-first Solid-CSS-Databox edge architecture and islandable microgrids.</td><td><strong>SDG 9:</strong> Industry, Innovation & Infrastructure</td></tr><tr><td><strong>Sustainable settlements</strong></td><td>Upgraded community grounds, dignified mobile living, and communal workshop facilities.</td><td><strong>SDG 11:</strong> Sustainable Cities & Communities</td></tr><tr><td><strong>Digital connectivity & education</strong></td><td>High-bandwidth access hubs aligned with international efforts like UNICEF's Project Connect.</td><td><strong>SDG 4 & 17:</strong> Quality Education & Partnerships</td></tr></tbody></table></div>` }
    ], next: 'cooperative-projects'
  },
  {
    slug: 'cooperative-projects', nav: 'Cooperative projects', title: 'Cross-site project infrastructure, procurement and supply chain hygiene.',
    description: 'How multi-site cooperative project infrastructure enables flexible commons innovation, fair contribution compensation, IP governance, and clean, verifiable supply chains.',
    eyebrow: '05 / Cooperative projects', intro: 'Enabling individuals and communities across multiple sites to collaborate on civics, humanitarian and SDG projects—facilitated by transparent IP management, flexible contribution models, and verifiable supply chain hygiene.',
    sections: [
      { id: 'cooperative-model', title: 'Flexible contribution & fair compensation', html: `<p>Cooperative infrastructure allows individuals across one or many sites to contribute towards projects as little or as much as they like—matching their own schedule, capacity and skills.</p><div class="numbered"><span class="index">01</span><div><h3>Permissionless initiation & non-barrier participation</h3><p>Anyone can start, prototype and develop projects without bureaucratic gatekeeping or scope lock-in. Because contributors are only compensated if a project achieves downstream success and delivers useful outputs, the community ground incurs zero financial speculation risk. People are free to experiment freely, build mutual aid solutions, and innovate organically.</p></div></div><div class="numbered"><span class="index">02</span><div><h3>Fair compensation for unmet obligations</h3><p>When contributors invest sweat equity, time or deferred costs into a project, these contributions are securely accounted for. If the project achieves funding, deployment or revenue, all unmet obligation costs are fairly compensated based on transparent contribution equity.</p></div></div><div class="numbered"><span class="index">03</span><div><h3>IP protection & rejecting predatory startup hubs</h3><p>Conventional "start-up hubs" and incubators too often expose unprotected creators to opportunistic vendors and scouts looking to harvest ideas from innovators who cannot afford costly litigation to defend their intellectual property. Our framework deliberately rejects this extractive dynamic. By anchoring contributions to cryptographic, W3C Solid-compatible data pods, transparent obligation ledgers, and open-source commons governance, creators maintain verifiable provenance and unalienable equity over their work across any interoperable platform—safeguarding the author's fundamental human right to the moral and material interests of their creations (UDHR Art. 27) and ensuring grassroots innovation directly advances the creator's own economic security.</p></div></div><div class="numbered"><span class="index">04</span><div><h3>Proportionate site revenue streams</h3><p>Participating host grounds receive a proportionate percentage of the obligation cost value for any projects they help develop. By providing physical workshop space, microgrid power, equipment and local stewardship, the sites earn an ongoing, self-sustaining revenue stream from project realisation—directly funding further local maintenance and civics upgrades.</p></div></div><div class="numbered"><span class="index">05</span><div><h3>Skills tuition, certified recognition & productivity uplift</h3><p>Hands-on project development serves as a practical incubator for teaching real-world engineering, modern digital tools, teamwork and small-business venturing. Whether or not a specific prototype commercialises, this innovation tuition is a high-value skills development activity—attracting vocational/educational funding, enabling certified micro-credential recognition, and directly uplifting regional productivity.</p></div></div>` },
      { id: 'interactive-guide', title: 'How it works: Guide for committees', html: `<p>Designed for community ground management committees, local trusts and site boards: explore how fair-value resource accounting protects volunteer contributors, prevents speculative risk, and secures a self-sustaining revenue stream for host community grounds.</p><div class="coop-widget" data-coop-stepper><div class="stepper-nav" role="tablist" aria-label="Cooperative lifecycle stages"><button class="stepper-btn" role="tab" aria-selected="true" data-step-btn><span class="num">STAGE 01</span><strong>Fair Value Scales</strong></button><button class="stepper-btn" role="tab" aria-selected="false" data-step-btn><span class="num">STAGE 02</span><strong>Project Lifecycle</strong></button><button class="stepper-btn" role="tab" aria-selected="false" data-step-btn><span class="num">STAGE 03</span><strong>The Payback Loop</strong></button><button class="stepper-btn" role="tab" aria-selected="false" data-step-btn><span class="num">STAGE 04</span><strong>Multi-Site Scale</strong></button></div><div class="stepper-panel" data-step-panel><span class="stepper-badge">Principle 01 · All resources have fair value</span><h4>Human time, equipment and space hold real capital worth</h4><p>In conventional commercial schemes, volunteers are asked to donate labour for free while speculative token systems demand upfront cash from consumers regardless of whether useful work is delivered. Our cooperative model recognises that an hour of skilled labour, an engineer's design, or a community ground workshop's 3-phase power has a measurable fair-market value.</p><p>When contributors work without upfront cash, they are effectively self-funding the project. Their time is logged as <strong>contribution equity</strong>, ensuring they are not exploited and will be fairly compensated when the project succeeds.</p></div><div class="stepper-panel" data-step-panel style="display:none"><span class="stepper-badge">Principle 02 · Staged development</span><h4>Projects grow through verified milestones</h4><p>Civics and humanitarian projects develop in clear stages: Blueprint Design &rarr; Local Fabrication & Prototyping &rarr; Community Testing &rarr; Operational Service.</p><p>Throughout these phases, diverse resources combine: cash grants, volunteer sweat equity, tool library machinery, and community ground host facilities. Every input is recorded in a tamper-proof edge ledger so all stakeholders have full visibility of project equity.</p><p><strong>Exploration without scope lock-in:</strong> projects develop at their own natural pace. Early-stage vetting never acts as a barrier to touching tools, because risk is held in sweat equity rather than public cash.</p></div><div class="stepper-panel" data-step-panel style="display:none"><span class="stepper-badge">Principle 03 · Fair compensation & site revenue</span><h4>Commercialisation pays down obligations & funds host grounds</h4><p>When the project delivers useful output—such as filtered drinking water, mobile vehicle repairs, or solar microgrid power—consumers and participants pay modest, predictable usage fees.</p><p>These revenues are split transparently: the majority pays down uncompensated contributor obligations until fully satisfied at fair rates. Simultaneously, <strong>the host ground receives its proportionate revenue share</strong>, securing ongoing funding for local community ground maintenance and permanent civics assets.</p></div><div class="stepper-panel" data-step-panel style="display:none"><span class="stepper-badge">Principle 04 · Cross-community federation</span><h4>Connecting local community grounds into a global commons</h4><p>Contributors can participate across multiple projects and multiple towns. A successful design developed at one regional ground can be federated and deployed by grounds across Australia or in developing nations.</p><p>By linking local physical facilities with international Sustainable Development Goals (SDGs), regional committees help bridge global infrastructure divides while building lasting wealth and prestige for their local town.</p></div><div class="sim-box" data-coop-simulator><h3>Interactive Payback Simulator: Model a community ground project</h3><p class="small">Choose a sample project preset or adjust the sliders to see how volunteer time and community ground facilities create tangible value, how fast obligations are paid down, and what the host community ground earns.</p><div class="sim-presets"><button class="sim-preset-btn active" data-sim-preset="solar">Solar Workshop</button><button class="sim-preset-btn" data-sim-preset="water">Water Filtration Hub</button><button class="sim-preset-btn" data-sim-preset="repair">Vehicle Repair Bay</button></div><div class="sim-grid"><div class="sim-field"><label for="sim-users-input">Active community users</label><input id="sim-users-input" type="range" min="10" max="100" step="5" value="40" data-sim-users><div class="val-row"><span>Estimated users:</span><span data-users-val>40 users</span></div></div><div class="sim-field"><label for="sim-fee-input">Weekly service fee per user</label><input id="sim-fee-input" type="range" min="2" max="25" step="1" value="8" data-sim-fee><div class="val-row"><span>Weekly fee:</span><span data-fee-val>$8/week</span></div></div></div><div class="sim-stats"><div class="sim-stat"><span>Volunteer Labour Equity</span><strong data-out-volunteer>$7,200</strong></div><div class="sim-stat"><span>Community Ground Facility Share</span><strong data-out-site>$3,500</strong></div><div class="sim-stat highlight"><span>Est. Payback Period</span><strong data-out-weeks>42 wks</strong></div><div class="sim-stat highlight"><span>Community Ground Annual Income</span><strong data-out-annual>$3,328</strong></div></div></div></div><div class="table-wrap"><table><thead><tr><th>Metric</th><th>Traditional Token / Extractive System</th><th>Cooperative Obligation System</th></tr></thead><tbody><tr><td><strong>Payment Timing</strong></td><td>Upfront, regardless of whether output is useful or delivered.</td><td>Generated from useful, deployed project derivatives over time.</td></tr><tr><td><strong>Value Focus</strong></td><td>Financial speculation, fee extraction and corporate profit.</td><td>Fair compensation for human time, skills, and host community facilities.</td></tr><tr><td><strong>Contributor Result</strong></td><td>Unpaid volunteer sweat equity is lost, uncredited, or exploited.</td><td>Uncompensated work creates an auditable obligation settled upon project success.</td></tr><tr><td><strong>Host Community Ground Impact</strong></td><td>Site absorbs wear-and-tear and utility costs without ongoing return.</td><td>Ground receives an ongoing, proportionate revenue stream from incubated projects.</td></tr></tbody></table></div>` },
      { id: 'project-pipeline', title: 'Version control for real-world projects', html: `<p>Collaborative physical projects function with the same mathematical and organisational rigour as modern version control systems (such as Git or Subversion), but adapted for physical tools, spatial facilities, and human craft. Instead of tracking code lines and software diffs, an auditable edge ledger tracks real-world <strong>resource commits</strong>—attributing time, trade skills, community ground workshop usage, and hardware components across a 3-stage gated milestone spine.</p><div class="pipeline-diagram"><div class="pipeline-stage-card"><div class="pipeline-stage-head"><span class="stage-tag">Stage 01</span><h4>Inception, Skills Tuition &amp; Open Exploration</h4><span class="version-badge">v1.0 · Discovery Release</span></div><div class="pipeline-tracks"><div class="track"><span class="track-title">Facilities, Tools &amp; Induction</span><ul><li><strong>Community ground facility access:</strong> assess workshop space, 3-phase microgrid power capacity, and vehicle access without bureaucratic delays.</li><li><strong>Supplier relationships:</strong> establish open accounts with local timber, steel, and electrical merchants.</li><li><strong>Safety &amp; tool induction:</strong> clear, supportive site safety guidelines that empower contributors to start immediately.</li></ul></div><div class="track"><span class="track-title">Open Exploration, Skills Tuition &amp; Venture Learning</span><ul><li><strong>Non-barrier project initiation:</strong> anyone can start a project branch; zero committee gatekeeping or premature scope lock-in.</li><li><strong>Skills &amp; small business tuition:</strong> hands-on mentoring in trade techniques, systems engineering, cost budgeting, and venture creation.</li><li><strong>Educational &amp; productivity uplift:</strong> logged training hours attract vocational grants and provide certified competency recognition.</li></ul></div></div><div class="pipeline-milestone"><span class="milestone-icon">✓</span><strong>Milestone 1 Gating: Publish 1st Stage Exploration &amp; Learning Log</strong><span>Public exploration log opened; training hours registered; zero speculative financial risk to the ground.</span></div></div><div class="pipeline-stage-card"><div class="pipeline-stage-head"><span class="stage-tag">Stage 02</span><h4>Assembly, Value-Chain &amp; Maker Crew</h4><span class="version-badge">v2.0 · Prototype Release</span></div><div class="pipeline-tracks"><div class="track"><span class="track-title">Value Chain, BOM &amp; Machine Scheduling</span><ul><li><strong>Bill of Materials (BOM):</strong> source certified circular materials, steel frames, and retested battery cells.</li><li><strong>Machine scheduling:</strong> coordinate access to heavy fabrication tools (lathes, plasma cutters, hoists).</li><li><strong>Testing environment:</strong> instrument prototypes with IoT telemetry and emergency isolation cutoffs.</li></ul></div><div class="track"><span class="track-title">Maker Crew, Trades &amp; Sweat Equity Commits</span><ul><li><strong>Commercialisation crew assembly:</strong> match licensed boilermakers, electricians, and apprentices.</li><li><strong>Logging resource commits:</strong> cryptographically record hours, skills, and materials to W3C Solid-compatible pods.</li><li><strong>Risk &amp; opportunity analysis:</strong> refine physical designs to eliminate assembly bottlenecks and wear points.</li></ul></div></div><div class="pipeline-milestone"><span class="milestone-icon">✓</span><strong>Milestone 2 Gating: Publish 2nd Stage Prototype</strong><span>Physical working model tested on the community ground; fair-value equity balance auditable.</span></div></div><div class="pipeline-stage-card"><div class="pipeline-stage-head"><span class="stage-tag">Stage 03</span><h4>Field Deployment, Service &amp; Payback Settlement</h4><span class="version-badge">v3.0 · Operational Release</span></div><div class="pipeline-tracks"><div class="track"><span class="track-title">Multi-Site Roadshow &amp; Community Service</span><ul><li><strong>Regional demonstrations:</strong> tour working unit to neighbouring community grounds, regional expos, and field days.</li><li><strong>End-user service agreements:</strong> onboard residents and community members with transparent micro-fees.</li><li><strong>Operational telemetry:</strong> monitor runtime hours, power output, and water volume automatically at the edge.</li></ul></div><div class="track"><span class="track-title">Obligation Settlement &amp; Retained Site Equity</span><div class="fork-box"><div class="fork-branch"><strong>Path A: Obligation Payback</strong><p>Service fees extinguish uncompensated contributor sweat equity and materials until fully reimbursed at fair value.</p></div><div class="fork-branch highlight"><strong>Path B: Retained Host Ground Dividend</strong><p>Host community ground trust retains permanent board auditing duties and a perpetual revenue percentage for site upkeep.</p></div></div></div></div><div class="pipeline-milestone"><span class="milestone-icon">✓</span><strong>Milestone 3 Gating: Publish 3rd Stage Release &amp; Active Service</strong><span>Derivative fully commercialised; contributor debt systematically paid down; ongoing trust revenue active.</span></div></div></div><div class="note"><p><strong>Practical tuition as an economic driver:</strong> Even if an exploratory project never reaches full commercial deployment, the process of building it delivers immediate value. Teaching people how to design, fabricate, and manage cooperative hardware creates accredited vocational competencies, attracts training co-funding, and permanently uplifts regional productivity.</p></div><div class="table-wrap"><table><thead><tr><th>Version Control Dimension</th><th>Software Version Control (Git / SVN)</th><th>Real-World Civics Project Control</th></tr></thead><tbody><tr><td><strong>Atomic Commit</strong></td><td>Code diff (lines added, modified, or removed).</td><td>Resource commit (human hours, trade qualifications, shed bay space, microgrid kWh).</td></tr><tr><td><strong>Contributor Identity</strong></td><td>GPG / SSH cryptographic key signature.</td><td>Decentralised, W3C Solid-interoperable Pod (verifiable licences, certifications, and task history across heterogeneous systems).</td></tr><tr><td><strong>Repository</strong></td><td>Digital repository (e.g., GitHub, GitLab).</td><td>Host Community Ground Edge Databox, workshop facility, and physical asset ledger.</td></tr><tr><td><strong>Branch &amp; Fork</strong></td><td>Feature branch or open-source fork.</td><td>Regional adaptation of an open civics blueprint (e.g., cyclone-rated vs. desert solar trailer).</td></tr><tr><td><strong>Release Milestone</strong></td><td>SemVer release tag (e.g., <code>v1.0.0</code>).</td><td>Gated stage milestone (Stage 1 Inception, Stage 2 Working Prototype, Stage 3 Field Service).</td></tr><tr><td><strong>Merge &amp; Settlement</strong></td><td>Code merged into <code>main</code> production branch.</td><td>Commercialised field deployment: usage fees flow back through commit tree to settle contributor obligations.</td></tr><tr><td><strong>Repository Dividend</strong></td><td>N/A (software repos rarely earn ongoing yields).</td><td><strong>Host Community Ground Perpetual Dividend:</strong> Ground earns ongoing percentage of derivative usage fees.</td></tr></tbody></table></div><div class="commit-widget" data-commit-inspector><div class="commit-widget-head"><h3>Interactive Real-World Commit Log</h3><p class="small">Click through sample commits below to see how trade skills, engineering design, community ground facilities, and circular hardware are logged into the project ledger with fair-value rates and repayment priorities.</p></div><div class="commit-body"><div class="commit-list" role="tablist" aria-label="Sample commits"><button class="commit-btn active" data-commit="0"><span class="commit-hash">commit c81b</span><strong>32 hrs Heavy Welding</strong><span class="commit-meta">Boilermaker · Sarah T.</span></button><button class="commit-btn" data-commit="1"><span class="commit-hash">commit f402</span><strong>28 Days Shed 3 Access</strong><span class="commit-meta">Facility · Community Ground Trust</span></button><button class="commit-btn" data-commit="2"><span class="commit-hash">commit e91a</span><strong>14 hrs Microgrid Config</strong><span class="commit-meta">Electrical CPEng · Marcus L.</span></button><button class="commit-btn" data-commit="3"><span class="commit-hash">commit d52c</span><strong>15kWh LiFePO4 Battery Bank</strong><span class="commit-meta">Materials · Regional Circular Depot</span></button></div><div class="commit-viewer" data-commit-viewer></div></div></div>` },
      { id: 'civics-infrastructure-sdgs', title: 'Physical civics infrastructure for SDG delivery', html: `<p>Delivering Sustainable Development Goals requires physical spaces engineered for both resident wellbeing and collaborative technical innovation.</p><div class="two-col"><div><h3>Active civics hubs & maker spaces</h3><p>Community grounds incorporate shared workshops, tool libraries and testing facilities, allowing contributors to prototype civics tech, circular materials and humanitarian hardware together.</p></div><div><h3>Resilient microgrid foundations</h3><p>Commercial-scale solar, battery storage and islandable microgrids ensure continuous power for fabrication, prototyping and emergency coordination during regional grid outages.</p></div></div><div class="note"><p><strong>Deployable blueprints for global impact:</strong> Modular infrastructure tested domestically—such as containerised water filtration and modular plastic pyrolysis—creates proven frameworks that can be exported to support international development efforts across SDG 4, 7, 9 and 11.</p></div>` },
      { id: 'procurement-transformation', title: 'Transforming procurement with edge ledgers', html: `<p>Combining decentralised digital identities with edge-metered infrastructure transforms community procurement into an automated, transparent and cost-effective process.</p><div class="flow"><div><span class="index">01</span><strong>Transactive ledgers</strong><p>Smart IoT metering logs energy, water and machine usage autonomously at the edge with cryptographic accuracy.</p></div><div><span class="index">02</span><strong>Micro-agreements</strong><p>Automates P2P resource dispatch and settlement between local creators and consumers without corporate brokers.</p></div><div><span class="index">03</span><strong>Zero vendor lock-in</strong><p>Open-source Linux edge software avoids recurring SaaS licences and centralised platform capture.</p></div><div><span class="index">04</span><strong>Clean supply chains</strong><p>Direct peer-to-peer contracting drastically lowers overheads and reinvests margins directly into community assets.</p></div></div>` },
      { id: 'supply-chain-hygiene', title: 'Supply chain hygiene & material provenance', html: `<p>Decentralised identity and open ledgers eliminate fraudulent claims and enforce strict supply chain compliance without bureaucratic delays.</p><ul><li><strong>Verifiable digital credentials:</strong> contractors, suppliers and fabricators authenticate via W3C Solid-compatible data pods, providing instant, tamper-proof proof of credentials, safety qualifications and historical delivery reliability across disparate systems.</li><li><strong>Circular material provenance:</strong> verifies the origin, structural integrity and safety testing of circular inputs—such as second-hand vehicle components, reclaimed timber, and modular building materials.</li><li><strong>Transparent funding compliance:</strong> public grants and community investment can be tracked directly from disbursement to tangible physical asset creation, meeting rigorous public auditing standards.</li></ul>` },
      { id: 'humanitarian-commons', title: 'Innovation for the global commons', html: `<p>Cooperative infrastructure transforms isolated regional grounds into a federated network of mutual aid, research and crisis resilience.</p><div class="table-wrap"><table><thead><tr><th>Dimension</th><th>Cooperative Infrastructure Mechanism</th><th>Societal & Economic Outcome</th></tr></thead><tbody><tr><td><strong>Humanitarian ICT</strong></td><td>Open-source digital tools and resilient edge hardware deployed across grounds.</td><td>Connectivity, education and disaster resilience for underserved populations.</td></tr><tr><td><strong>Resource Federation</strong></td><td>Inter-site pooling of specialised machinery, parts inventories and technical skills.</td><td>Dramatically reduces redundant capital expenses across participating communities.</td></tr><tr><td><strong>Site Revenue Streams</strong></td><td>Host community grounds earn a proportionate percentage of project obligation cost value.</td><td>Generates recurring, self-sustaining revenue for local community ground trusts and civics maintenance.</td></tr><tr><td><strong>Uplifting Human Value &amp; Equity</strong></td><td>Voluntary community logging of trade mentoring, repair assistance and site stewardship.</td><td>Translates latent human contributions into recognised community value, accredited vocational competencies, and lasting personal equity.</td></tr></tbody></table></div>` }
    ], next: 'journey-out'
  },
  {
    slug: 'journey-out', nav: 'The journey out', title: 'A springboard for life, not a permanent car park.',
    description: 'How community grounds act as a catalytic springboard for positive life transitions, and how former residents and wider community members stay connected through civics projects.',
    eyebrow: '06 / The journey out', intro: 'The community grounds ecosystem is designed as a catalytic stepping stone, not an endpoint. Our ultimate measure of success is “The Journey Out”—the moment someone leverages our civics infrastructure to transition into their next positive chapter, while remaining connected to local projects.',
    sections: [
      { id: 'transition-framework', title: 'The springboard: Transitioning forward', html: `<p>Rather than functioning as a long-term car park or a holding pen for disadvantage, community grounds serve as a launchpad for personal autonomy, skills uplift, and economic renewal. By providing a secure, guaranteed <strong>$15 per night ($105/week) concession floor</strong> supported by generative solar and edge compute infrastructure, the site decouples foundational living costs from financial extraction.</p><p>This affordability restores the cognitive agency and financial bandwidth necessary for individuals and families to plan their long-term futures. True success is not measured by how many people remain on the grounds indefinitely, but by <strong>the velocity and quality of the journey out</strong>—how effectively participants use this stability to rebuild their lives, launch ventures, or find permanent regional homes.</p><div class="two-col"><div><h3>Changing lives on the ground</h3><p>While on site, participants utilise commercial-scale solar microgrids, high-speed connectivity, and shared maker workshops to complete vocational study, recover from personal trauma, care for family, or bootstrap small enterprises without the crushing stress of urban debt.</p></div><div><h3>Transitioning to the next chapter</h3><p>When circumstances evolve, individuals transition out into traditional homeownership, regional rental housing, completed travel, or permanent social housing. They leave with repaired vehicles, accredited skills, and financial breathing room.</p></div></div>` },
      { id: 'departure-categories', title: 'Pathways of independence & transition', html: `<p>Understanding the diverse reasons people leave validates the wide spectrum of people utilising community grounds. The journey out takes multiple distinct, positive forms:</p><div class="numbered"><span class="index">01</span><div><h3>The Completed Journey: Travellers & working nomads</h3><p>Domestic road-trippers, international backpackers, seasonal agricultural workers, and digital nomads who utilise the secure amenities, microgrid power, and internet during their working travels. Their journey out represents the planned, successful, and safe conclusion of their time on the road as they return home or embark on their next career deployment.</p></div></div><div class="numbered"><span class="index">02</span><div><h3>The Community Settler: Regional integration & local housing</h3><p>Nomads and mobile workers who establish deep roots in the host town, securing local employment in trades, healthcare, agriculture, or services. Having fallen in love with the area and built local social ties, they transition smoothly from on-site transitional accommodation into permanent rental housing or home purchase in the local town.</p></div></div><div class="numbered"><span class="index">03</span><div><h3>The Successful Innovator: Project commercialisation & homeownership</h3><p>Grassroots inventors, tradespeople, and creators who utilise the active civics hubs, tool libraries, and open-source version-controlled project frameworks. As their cooperative hardware prototypes or small ventures achieve commercial deployment, they receive fair obligation payback and enterprise revenue—independently funding their transition into traditional homeownership without crippling debt.</p></div></div><div class="numbered"><span class="index">04</span><div><h3>The Strategic Reset: Asset lifecycle & life stabilisation</h3><p>Capable individuals navigating acute life milestones—such as relationship separation or divorce, business restructuring, caring duties, or probate where capital is temporarily locked up. The grounds provide an affordable, dignified sanctuary where they can live securely within a modest budget until their life events resolve, legal settlements finalise, and tied-up funds are released to buy or rent a home.</p></div></div><div class="numbered"><span class="index">05</span><div><h3>The Supported Transition: A dignified bridge to public housing</h3><p>Individuals who face long-term health, physical disability, or age-related limitations requiring permanent social support. Rather than enduring the degradation of sleeping rough or exhausting public funds on temporary emergency motels, the ground provides an immediate, safe, and dignified haven while residents wait for placement in permanent public or community housing.</p></div></div>` },
      { id: 'transition-matrix', title: 'Cohort profiles, stepping stones & destinations', html: `<p>The following matrix outlines how the ground's generative infrastructure serves as a tailored springboard across diverse participant cohorts:</p><div class="table-wrap"><table><thead><tr><th>Participant Cohort</th><th>The Stepping Stone on the Ground</th><th>The Transition Trigger</th><th>The Journey Out Destination</th></tr></thead><tbody><tr><td><strong>The Innovator & Maker</strong></td><td>Shared workshops, 3-phase microgrid power, tool libraries, and verifiable resource commits.</td><td>Cooperative project commercialisation, grant milestone, or trade business growth.</td><td>Funded homeownership, commercial workshop lease, or independent enterprise.</td></tr><tr><td><strong>The Strategic Reset</strong></td><td>$15/night concession floor, restored cognitive bandwidth, and non-extractive amenities.</td><td>Resolution of probate, divorce settlement, asset sale, or financial stabilisation.</td><td>Return to private rental or owner-occupied residential housing.</td></tr><tr><td><strong>The Community Settler</strong></td><td>Low-cost local base, community ground events, and integration with regional town networks.</td><td>Securing long-term regional employment and establishing local friendships.</td><td>Permanent residency in a local town home, contributing to regional population growth.</td></tr><tr><td><strong>The Student & Apprentice</strong></td><td>High-speed digital access, quiet study zones, vehicle bays, and hands-on maker mentorship.</td><td>Completion of university degree, TAFE trade certification, or apprenticeship.</td><td>Relocation to professional career role or trade contractor setting.</td></tr><tr><td><strong>The Working Traveller</strong></td><td>Dependable utilities, secure vehicle parking, clean ablutions, and flexible seasonal stays.</td><td>Completion of seasonal work contract or regional travel itinerary.</td><td>Return to home city, overseas base, or transition to next travel region.</td></tr><tr><td><strong>The Supported Resident</strong></td><td>Universal safe haven, non-conditional shelter during illness, and community care access.</td><td>Allocation of permanent social or supported public housing.</td><td>Permanent public housing dwelling with ongoing community health links.</td></tr></tbody></table></div>` },
      { id: 'beyond-the-campsite', title: 'A continued connection: Beyond the campsite', html: `<p>A vital principle of the community grounds model is that the ecosystem belongs to the entire regional town. It is not an isolated enclave or a segregated campsite. The initiative operates at its best when the wider community participates actively in projects, events, and facilities—whether they live in a mobile home on site, reside in a house in town, or have previously transitioned out.</p><div class="two-col"><div><h3>Inclusive community participation</h3><p>Locals who live in permanent town housing can utilise the shared workshops, join cooperative solar projects, participate in disaster-resilience drills, and mentor young apprentices. Participation is defined by interest and contribution equity, not by where a person sleeps at night.</p></div><div><h3>Portable data pods & earned equity</h3><p>Leveraging open, W3C Solid-interoperable standards, former residents maintain portable digital pods containing their verified task history, trade credentials, and logged project equity across whatever technologies or platforms their future endeavours employ. Moving into a house never severs a contributor's stake in projects they helped build.</p></div></div><div class="note"><p><strong>Stewardship without borders:</strong> Former residents frequently return to the grounds as experienced project leaders, trade instructors, or community trust board members. By maintaining this continuous civics connection on fair terms, community grounds transform transitional shelter into permanent regional social capital.</p></div>` }
    ], next: 'review'
  },
  {
    slug: 'review', nav: 'Review & next steps', title: 'A proposal worth making clear—and testing carefully.',
    description: 'The proposal framework, operational hypotheses, whole-of-system economics and pilot measures behind the community grounds initiative.',
    eyebrow: '07 / Review & next steps', intro: 'This proposal synthesises lived research, practical field development, and operational frameworks into a model communities and councils can review and test together. It outlines a concrete roadmap for establishing initial regional pilots.',
    sections: [
      { id: 'reading-the-source', title: 'How to read this proposal', html: `<p>This proposal was developed from direct on-the-ground research, living in a mobile camper setting, and investigating the real-world economics of regional resilience, vehicle maintenance, and distributed community infrastructure. To evaluate the initiative constructively, it helps to distinguish between its core foundations, operational modelling, and the broader economic baseline:</p><div class="numbered"><span class="tag">Core</span><div><h3>Foundational principles & lived design</h3><p>Community grounds; dedicated support to acquire and maintain roadworthy mobile dwellings and tow vehicles; solar, battery, and amenity hubs; purposeful maker workshops; local digital edge infrastructure; and open-standard, user-owned data architecture. These represent the core design principles developed through lived experience on the ground.</p></div></div><div class="numbered"><span class="tag question">Pilot</span><div><h3>Untested operational modelling</h3><p>Specific loan amortisation structures, self-funding site thresholds, microgrid energy export arbitrage, and cooperative network access models are working hypotheses. They need to be calibrated, tested, and validated in a real-world regional demonstration rather than assumed as finished commercial solutions.</p></div></div><div class="numbered"><span class="tag question">Context</span><div><h3>Evaluating against existing cost-per-case</h3><p>Crucially, the operational modelling must be weighed against the real status quo: the enormous, recurring costs of unassisted hardship where no material infrastructure exists. When evaluated against acute emergency healthcare, psychiatric crisis beds, policing and court interventions, lost earning capacity from trauma, and diminished Quality of Life Years (QALY), catalytic civics infrastructure offers a preventative, wealth-building alternative to perpetual crisis expenditure.</p></div></div>` },
      { id: 'economic-thesis', title: 'The economic proposition & whole-of-system accounting', html: `<p>The core economic thesis inverts traditional landlordism by coupling physical shelter with <strong>generative physical and digital infrastructure</strong>. Commercial rooftop solar exports, battery grid arbitrage, and local edge compute services generate external site revenue, decoupling the ground's operational viability from high rental extraction. This allows grounds to maintain a <strong>$15/night ($105/week) concession floor</strong> (30% of commercial rates, or 17.5% of income) alongside standard nomad ($30–$35/night) and commercial ($50/night) tariffs.</p><p>To evaluate this model fairly, it cannot be measured against a hypothetical zero-cost baseline. In the absence of stable material infrastructure, society already pays massive per-person costs through fragmented emergency interventions. The table below contrasts the proposal's economic hypotheses with the true whole-of-system cost per case:</p><div class="table-wrap"><table><thead><tr><th>Economic Hypothesis</th><th>Existing Cost-of-Inaction per Case</th><th>Evidence a Pilot Would Need to Verify</th></tr></thead><tbody><tr><td><strong>Generative Revenue Decoupling:</strong> Solar exports and edge compute cover baseline site capital and utility overheads.</td><td>Recurring public subsidies and deficit funding for temporary crisis accommodation facilities.</td><td>Net metered solar generation, feed-in revenues, battery arbitrage margins, and local compute service fees measured across all seasons.</td></tr><tr><td><strong>Living Cost Viability ($15/night floor):</strong> Concession card holders live sustainably within ~$600/wk without entering crisis debt.</td><td>Acute healthcare presentations, emergency ambulance callouts, and psychiatric crisis admissions driven by severe housing stress.</td><td>Actual resident budgets, essential living expenses, vehicle upkeep reserves, and verified personal savings buffers.</td></tr><tr><td><strong>Universal Safe Haven:</strong> Shelter remains secure even if residents are severely unwell or unable to contribute sweat equity.</td><td>Police interventions, court appearances, custodial detention, and punitive enforcement costs associated with rough sleeping and displacement.</td><td>Continuity of stay during illness, non-punitive tenancy records, and absence of eviction due to temporary loss of task capacity.</td></tr><tr><td><strong>Trauma Recovery & Earning Capacity:</strong> Restored cognitive agency, vocational workshops, and digital pods rebuild livelihoods.</td><td>Permanent loss of human capital, intergenerational welfare dependency, and severe degradation in Quality-Adjusted Life Years (QALY).</td><td>Participation in maker projects, accredited skill attainment, business bootstrapping, and transition into independent employment.</td></tr><tr><td><strong>Tiered Cross-Subsidisation:</strong> Full-fee tourists ($50/night) and nomads ($30–$35/night) support site reserves.</td><td>Loss of regional tourism spend and failure to capture mobile remote-worker economic contribution in regional towns.</td><td>Seasonal occupancy splits, revenue per site category, and net contribution to shared tooling and maintenance reserves.</td></tr><tr><td><strong>Catalytic Public Spending:</strong> Co-investment in regional civics assets yields higher return than emergency motels.</td><td>State expenditures often exceeding $150–$300/night for short-term emergency hotel vouchers that produce zero enduring public assets.</td><td>Comparative cost per person-day between temporary crisis hotel vouchers and permanent, multi-use community ground infrastructure.</td></tr></tbody></table></div><p class="small">This proposal establishes a dignified, asset-building alternative for transitional living; by addressing root material needs early, it substantially reduces acute whole-of-government expenditure across health, justice, and social services.</p>` },
      { id: 'pilot-questions', title: 'Decisions before a pilot', html: `<details open><summary>Where could a first ground work?</summary><p>Identify a candidate with willing local partners. Assess existing users, ownership, amenities, roofs, energy demand, access, hazards, permissions and event commitments. No pilot location has been selected in the source.</p></details><details><summary>Who is it for, and what does participation mean?</summary><p>Define suitability, accessibility, length of stay, fees, residents' rights, support options and an exit pathway. Involve intended participants in the design.</p></details><details><summary>Who pays, owns and operates?</summary><p>Separate infrastructure funding, home or vehicle finance and ongoing operations. Identify who owns each asset, holds obligations and covers repairs or revenue shortfalls. The proposed public fund is not an announced funding commitment.</p></details><details><summary>What is the smallest useful first stage?</summary><p>Agree which basic facilities and support must work from day one. Later energy coordination, digital portability and international adaptation can be developed from evidence gathered at the first ground.</p></details><details><summary>How would success—or failure—be recognised?</summary><p>Set baseline measures, a review period and decision criteria with residents and local partners. Include cost overruns, poor living conditions, operational disruption and exclusion as possible findings to act on.</p></details>` },
      { id: 'sources', title: 'Sources & scope', html: `<ol class="source-list"><li><strong>Community Grounds & Resilient Transitional Human Renewal Strategy</strong><small>Primary concept source. Developed through lived experience, field research, and technical design outlining community grounds infrastructure and cooperative operating models.</small></li><li><a href="https://github.com/mediaprophet/Solid-CSS-Databox">Solid-CSS-Databox (GitHub)</a><small>Open-source reference architecture for containerised Community Solid Server (CSS) edge appliances, IoT telemetry and W3C Solid-interoperable local data pods.</small></li><li><a href="https://solidproject.org/about">Solid Project — About Solid</a><small>Open-standard specification enabling interoperability across diverse systems and technologies. Consulted 15 September 2026; not a proprietary specification for this project.</small></li><li><a href="https://projectconnect.unicef.org/">UNICEF — Project Connect</a><small>External initiative referenced by the author. Included as context, not evidence of affiliation or delivery commitments.</small></li></ol><p>These are initial concept pages for review. Detailed legal, engineering, funding and financial feasibility work remains to be done for a specific implementation.</p>` }
    ], next: 'eoi'
  },
  {
    slug: 'eoi', nav: 'Express interest', title: 'Support, partnership & local opportunity.',
    description: 'Register an expression of interest in supporting, informing or participating in a future civics.au Community Grounds pilot.',
    eyebrow: '08 / Expression of interest', intro: 'We are seeking early conversations with people and organisations who may help shape, support or take part in future Community Grounds pilots.',
    sections: [
      { id: 'eoi-form', title: 'Expression of interest form', html: `<script src="https://challenges.cloudflare.com/turnstile/v0/api.js" async defer></script>
<div id="eoi-alert" class="eoi-alert" role="alert" aria-live="polite" style="display:none"></div>
<div class="eoi-context"><p><strong>Community Grounds are a proposal, not yet an operating program.</strong> We welcome expressions of interest from community organisations, businesses, foundations, service providers, landholders, researchers and people who may wish to participate. Support may be financial, practical, technical, in-kind or community-based. An EOI does not commit either party.</p><p>Grounds are proposed as participatory places for temporary stays, shared activity and local connection—not permanent residential estates. Subject to site arrangements and individual circumstances, participants would ordinarily move on after about three months.</p><p class="small">Visible non-government support may help inform future discussions about public co-investment. Any government participation would be subject to separate decisions, eligibility and approvals.</p></div>
<form id="eoi" class="eoi-form" method="post" action="/eoi" novalidate>
  <input type="text" name="website" id="eoi-website" tabindex="-1" autocomplete="off" aria-hidden="true" style="display:none!important;position:absolute;left:-9999px">
  <div class="eoi-row eoi-row--half">
    <div class="eoi-field">
      <label for="eoi-name">Full name <span class="eoi-req" aria-hidden="true">*</span></label>
      <input type="text" id="eoi-name" name="name" autocomplete="name" required placeholder="Your name">
    </div>
    <div class="eoi-field">
      <label for="eoi-email">Email address <span class="eoi-req" aria-hidden="true">*</span></label>
      <input type="email" id="eoi-email" name="email" autocomplete="email" required placeholder="you@example.com">
    </div>
  </div>
  <div class="eoi-row eoi-row--half">
    <div class="eoi-field">
      <label for="eoi-organisation">Organisation <span class="eoi-opt">(if applicable)</span></label>
      <input type="text" id="eoi-organisation" name="organisation" autocomplete="organization" placeholder="Organisation or group name">
    </div>
    <div class="eoi-field">
      <label for="eoi-role">Role <span class="eoi-opt">(if applicable)</span></label>
      <input type="text" id="eoi-role" name="role" autocomplete="organization-title" placeholder="Your role or connection">
    </div>
  </div>
  <div class="eoi-row eoi-row--half">
    <div class="eoi-field">
      <label for="eoi-phone">Phone <span class="eoi-opt">(optional)</span></label>
      <input type="tel" id="eoi-phone" name="phone" autocomplete="tel" placeholder="04xx xxx xxx">
    </div>
    <div class="eoi-field">
      <label for="eoi-state">State / Territory</label>
      <select id="eoi-state" name="state">
        <option value="">— Select —</option>
        <option>ACT</option><option>NSW</option><option>NT</option>
        <option>QLD</option><option>SA</option><option>TAS</option>
        <option>VIC</option><option>WA</option><option>International</option>
      </select>
    </div>
  </div>
  <div class="eoi-field">
    <label for="eoi-respondent-type">What best describes your interest? <span class="eoi-req" aria-hidden="true">*</span></label>
    <select id="eoi-respondent-type" name="respondent_type" required>
      <option value="">— Select the closest match —</option>
      <option value="participant">I may wish to participate in a future Community Ground</option>
      <option value="community-organisation">I represent a community or volunteer organisation</option>
      <option value="business-service-provider">I represent a business, retailer or service provider</option>
      <option value="funder">I represent a foundation, funder or social investor</option>
      <option value="site-landholder">I have a potential site, land, venue or facilities</option>
      <option value="research-technical">I can offer research, technical or professional expertise</option>
      <option value="government-public-body">I represent a government or public body</option>
      <option value="media">I am from media or journalism</option>
      <option value="other">Another form of interest</option>
    </select>
  </div>

  <fieldset class="eoi-fieldset" id="eoi-shared-support">
    <legend>Where could this be relevant?</legend>
    <div class="eoi-row eoi-row--half">
      <div class="eoi-field"><label for="eoi-scope">Geographic scope</label><select id="eoi-scope" name="geographic_scope"><option value="">— Select —</option><option value="national">National or multi-region</option><option value="state-territory">A state or territory</option><option value="regional-local">A particular regional or local area</option><option value="specific-site">A particular site or property</option><option value="unsure">Not sure yet</option></select></div>
      <div class="eoi-field"><label for="eoi-location">Town, region or site <span class="eoi-opt">(optional)</span></label><input type="text" id="eoi-location" name="location" placeholder="e.g. Northern Rivers, NSW"></div>
    </div>
  </fieldset>

  <fieldset class="eoi-branch" data-for="participant" hidden>
    <legend>Participation interest</legend>
    <p class="eoi-help">This is an early EOI, not an application for a place to stay.</p>
    <div class="eoi-checks"><label><input type="checkbox" name="participation_interest" value="temporary-stay"> A temporary stay at a future ground</label><label><input type="checkbox" name="participation_interest" value="shared-activities"> Shared activities, projects or contribution</label><label><input type="checkbox" name="participation_interest" value="practical-support"> Access to practical support</label><label><input type="checkbox" name="participation_interest" value="local-connection"> A connection to a particular place or community</label></div>
    <div class="eoi-field"><label for="eoi-longer-connection">Is there a reason you may need to remain connected to one location for longer? <span class="eoi-opt">(optional)</span></label><textarea id="eoi-longer-connection" name="longer_connection" rows="3" placeholder="Please do not include sensitive personal or medical details at this stage."></textarea></div>
  </fieldset>

  <fieldset class="eoi-branch" data-for="community-organisation business-service-provider funder site-landholder research-technical government-public-body other" hidden>
    <legend>How might you or your organisation contribute?</legend>
    <div class="eoi-checks"><label><input type="checkbox" name="support_type" value="funding"> Philanthropic, catalytic or project funding</label><label><input type="checkbox" name="support_type" value="social-investment"> Social investment or patient capital</label><label><input type="checkbox" name="support_type" value="land-facilities"> Land, venue, facilities or accommodation</label><label><input type="checkbox" name="support_type" value="products-services"> Products, equipment or skilled services</label><label><input type="checkbox" name="support_type" value="discounts"> Discounts or in-kind offers</label><label><input type="checkbox" name="support_type" value="employment-training"> Employment, training, volunteering or inclusion activities</label><label><input type="checkbox" name="support_type" value="research-advice"> Research, evaluation or professional advice</label><label><input type="checkbox" name="support_type" value="community-delivery"> Community engagement or local delivery partnership</label><label><input type="checkbox" name="support_type" value="other"> Another kind of support</label></div>
  </fieldset>

  <fieldset class="eoi-branch" data-for="funder" hidden>
    <legend>Funding conversation</legend>
    <div class="eoi-row eoi-row--half"><div class="eoi-field"><label for="eoi-funding-stage">Stage of interest</label><select id="eoi-funding-stage" name="funding_stage"><option value="">— Select —</option><option value="exploring">Exploring the proposal</option><option value="briefing">Interested in a briefing</option><option value="pilot">Interested in a pilot conversation</option><option value="future-co-investment">Considering future co-investment</option></select></div><div class="eoi-field"><label for="eoi-timing">Indicative timing <span class="eoi-opt">(optional)</span></label><input type="text" id="eoi-timing" name="timing" placeholder="e.g. next 6–12 months"></div></div>
  </fieldset>

  <fieldset class="eoi-branch" data-for="business-service-provider" hidden>
    <legend>Service, product or discount offer</legend>
    <div class="eoi-field"><label for="eoi-offer">What could you offer? <span class="eoi-opt">(optional)</span></label><textarea id="eoi-offer" name="offer" rows="4" placeholder="Describe the product, service, discount, capacity or conditions."></textarea></div>
  </fieldset>

  <fieldset class="eoi-branch" data-for="site-landholder" hidden>
    <legend>Potential site or facilities</legend>
    <div class="eoi-field"><label for="eoi-site-details">What is available? <span class="eoi-opt">(optional)</span></label><textarea id="eoi-site-details" name="site_details" rows="4" placeholder="Location, facilities, ownership or permission position, and any known constraints."></textarea></div>
  </fieldset>

  <div class="eoi-field">
    <label for="eoi-story">Why does this proposal matter to you? <span class="eoi-opt">(optional)</span></label>
    <textarea id="eoi-story" name="story" rows="5" placeholder="Share the need, opportunity, experience or local context that makes you interested."></textarea>
  </div>
  <div class="eoi-field">
    <label for="eoi-message">Anything else we should know? <span class="eoi-opt">(optional)</span></label>
    <textarea id="eoi-message" name="message" rows="4" placeholder="Questions, a proposed next step, or further context."></textarea>
  </div>

  <fieldset class="eoi-fieldset eoi-consent">
    <legend>How may we use what you share?</legend>
    <p class="eoi-help">Your submission is private by default. We will contact you for confirmation before publishing a story, quotation, organisation name or identifying detail.</p>
    <div class="eoi-radios"><label><input type="radio" name="publication_permission" value="private" checked> Keep this submission private; use it only to respond to this EOI.</label><label><input type="radio" name="publication_permission" value="private-discussion"> The team may discuss it privately with prospective delivery or funding partners.</label><label><input type="radio" name="publication_permission" value="anonymised-contact"> You may contact me about publishing an anonymised summary or quotation.</label><label><input type="radio" name="publication_permission" value="named-contact"> You may contact me about publishing an approved named summary or quotation.</label></div>
  </fieldset>
  <div class="eoi-turnstile">
    <div class="cf-turnstile" data-sitekey="0x4AAAAAAE1cw59__Sm6r8Qa" data-theme="light"></div>
    <p class="eoi-privacy">Your information is sent directly to the civics.au team, with a private JSON-LD record attached for internal cataloguing. We do not publish or share identifying information without your confirmation. The CAPTCHA above is provided by <a href="https://www.cloudflare.com/products/turnstile/" target="_blank" rel="noopener">Cloudflare Turnstile</a> — it does not use cookies or track your behaviour.</p>
  </div>
  <div class="eoi-actions">
    <button type="submit" id="eoi-submit" class="button">Send expression of interest <span aria-hidden="true">↗</span></button>
  </div>
</form>
<script>
(function(){
  var params = new URLSearchParams(location.search);
  var err = params.get('error');
  var alert = document.getElementById('eoi-alert');
  if(err && alert){
    var code = params.get('code');
    var details = params.get('details');
    var sendMsg = 'Something went wrong sending your submission. Please try again or email info@civics.au directly.';
    if(code || details){
      sendMsg = 'Email delivery failed' + (code ? ' (HTTP ' + code + ')' : '') + (details ? ': ' + details : '') + '. Please try again later or email info@civics.au directly.';
    }
    var msgs = {
      validation: 'Please fill in your name and a valid email address.',
      captcha: 'The CAPTCHA check did not pass. Please try again.',
      send: sendMsg
    };
    alert.textContent = msgs[err] || 'An unexpected error occurred. Please try again.';
    alert.style.display = 'block';
  }
  var form = document.getElementById('eoi');
  if(form){
    var respondentType = form.querySelector('#eoi-respondent-type');
    var branches = form.querySelectorAll('.eoi-branch');
    function updateBranches(){
      var type = respondentType.value;
      branches.forEach(function(branch){
        var matches = (branch.getAttribute('data-for') || '').split(' ').indexOf(type) !== -1;
        branch.hidden = !matches;
        branch.querySelectorAll('input, select, textarea').forEach(function(field){ field.disabled = !matches; });
      });
    }
    respondentType.addEventListener('change', updateBranches);
    updateBranches();
    form.addEventListener('submit', function(e){
      var name = form.querySelector('#eoi-name').value.trim();
      var email = form.querySelector('#eoi-email').value.trim();
      if(!name || !email || !email.includes('@') || !respondentType.value){
        e.preventDefault();
        if(alert){
          alert.textContent = 'Please fill in your name, a valid email address, and the type of interest.';
          alert.style.display = 'block';
          alert.scrollIntoView({behavior:'smooth',block:'nearest'});
        }
      }
    });
  }
})();
</script>` }
    ]
  }
];
